namespace Game.Runtime {
// Capability made only after the original request-context guard; not a serialized gameplay permission.
internal sealed class SourceCanonicalBirthRequest {
 internal readonly EntityManager Manager;internal readonly GeneratedBuildingRegistration Factory;internal readonly BuildingRuntimeSpawnRequest Request;internal bool Claimed;
 private SourceCanonicalBirthRequest(EntityManager em,GeneratedBuildingRegistration factory,BuildingRuntimeSpawnRequest request){Manager=em;Factory=factory;Request=request;}
 internal static SourceCanonicalBirthRequest FromOriginalContext(EntityManager em,GeneratedBuildingRegistration factory,BuildingRuntimeSpawnRequest request){if(em==null||factory==null||request.AuthoredStartingGrant!=0||request.Status!=BuildingRuntimeSpawnRequest.Pending||request.HasOwnerFaction==0||request.RequestId<=0||request.RequestKind!=BuildingRuntimeSpawnRequest.KindSkirmishPaidConstruction)throw new NotSupportedException("One actual native paid-construction request context required");ValidatePending(em,request);return new SourceCanonicalBirthRequest(em,factory,request);}
 internal static void ValidatePending(EntityManager em,BuildingRuntimeSpawnRequest request){using var q=em.CreateEntityQuery(typeof(BuildingRuntimeStateTag));if(q.CalculateEntityCount()!=1)throw new NotSupportedException("Exact native building-request boundary required");var e=q.GetSingletonEntity();if(!em.HasBuffer<BuildingRuntimeSpawnRequest>(e))throw new NotSupportedException("Actual pending native building-request buffer required");int matches=0;foreach(var row in em.GetBuffer<BuildingRuntimeSpawnRequest>(e,true))if(row.RequestId==request.RequestId){if(!CanonicalStorageBank.Same(row,request)||row.Status!=BuildingRuntimeSpawnRequest.Pending)throw new NotSupportedException("Native building request changed before source factory");matches++;}if(matches!=1)throw new NotSupportedException("Unique actual pending native building request required");}
 internal void Validate(EntityManager em,GeneratedBuildingRegistration factory){if(!ReferenceEquals(Manager,em)||!ReferenceEquals(Factory,factory)||Claimed)throw new NotSupportedException("Foreign, repeated or closed native factory authority");ValidatePending(em,Request);}
}
internal sealed class SourceCanonicalFactoryScope:IDisposable {
 internal readonly EntityManager Manager;internal readonly SourceCanonicalBirthRequest Permit;internal readonly int RuntimeId;internal readonly Vector2Int Origin;internal Entity Actor;internal int Created;internal bool Completed,Disposed;
 internal SourceCanonicalFactoryScope(EntityManager em,SourceCanonicalBirthRequest permit,int id,Vector2Int origin){Manager=em;Permit=permit;RuntimeId=id;Origin=origin;}
 internal void NoteCreated(Entity entity){Created++;if(Created==1)Actor=entity;}
 internal void ValidateActor(Entity entity){if(Disposed||Created!=1||Actor!=entity||!Manager.Exists(entity)||!Manager.HasComponent<RuntimeBuildingCombatTag>(entity)||!Manager.HasComponent<RuntimeBuildingCombatInfo>(entity))throw new NotSupportedException("Exactly one actual native combat actor must own storage birth");var info=Manager.GetComponentData<RuntimeBuildingCombatInfo>(entity);if(info.RuntimeBuildingId!=RuntimeId||info.OriginCell.x!=Origin.x||info.OriginCell.y!=Origin.y)throw new NotSupportedException("Actual native runtime building identity/origin mismatch");}
 internal void Complete(Entity entity){ValidateActor(entity);Completed=true;}
 public void Dispose(){if(Disposed)return;Disposed=true;Manager.EndCanonicalFactory(this);}
}
internal sealed class SourceCanonicalProfileScope:IDisposable {
 internal readonly EntityManager Manager;internal readonly Entity Actor;internal readonly bool CanAdd;internal bool Disposed;
 internal SourceCanonicalProfileScope(EntityManager em,Entity actor,bool add){Manager=em;Actor=actor;CanAdd=add;}
 public void Dispose(){if(Disposed)return;Disposed=true;Manager.EndCanonicalProfile(this);}
}
}
namespace Unity.Entities {
public sealed partial class EntityManager {
 Game.Runtime.SourceCanonicalFactoryScope canonicalFactoryScope;Game.Runtime.SourceCanonicalProfileScope canonicalProfileScope;
 readonly HashSet<string> canonicalFactoryRequestIds=new HashSet<string>(StringComparer.Ordinal);
 readonly Dictionary<Entity,Game.Runtime.SourceCanonicalFactoryScope> canonicalPendingBirths=new Dictionary<Entity,Game.Runtime.SourceCanonicalFactoryScope>();
 internal void RequireCanonicalFactoryRequest(Game.Runtime.SourceCanonicalBirthRequest request,Game.Runtime.GeneratedBuildingRegistration factory){if(bank==null)return;if(!bank.IsFreshSourceOwnedBy(this)||request==null)throw new NotSupportedException("Fresh source factory request authority required before construction");request.Validate(this,factory);}
 internal Game.Runtime.SourceCanonicalFactoryScope BeginCanonicalFactory(Game.Runtime.SourceCanonicalBirthRequest request,Game.Runtime.GeneratedBuildingRegistration factory,int runtimeId,Vector2Int origin){if(bank==null)return null;RequireCanonicalFactoryRequest(request,factory);if(canonicalFactoryScope!=null||canonicalProfileScope!=null||runtimeId<=0)throw new NotSupportedException("Nested/invalid canonical building factory scope");string requestKey=request.Request.PlanEntity.Index+":"+request.Request.PlanEntity.Version+":"+request.Request.RequestId;if(!canonicalFactoryRequestIds.Add(requestKey))throw new NotSupportedException("Native factory request already consumed");request.Claimed=true;canonicalFactoryScope=new Game.Runtime.SourceCanonicalFactoryScope(this,request,runtimeId,origin);return canonicalFactoryScope;}
 internal void NoteCanonicalFactoryEntity(Entity entity){canonicalFactoryScope?.NoteCreated(entity);}
 internal void EndCanonicalFactory(Game.Runtime.SourceCanonicalFactoryScope scope){if(!ReferenceEquals(canonicalFactoryScope,scope))throw new InvalidOperationException("Canonical factory scope lineage");canonicalFactoryScope=null;if(scope.Completed&&Exists(scope.Actor)){if(canonicalPendingBirths.ContainsKey(scope.Actor))throw new InvalidOperationException("Duplicate pending factory actor");canonicalPendingBirths.Add(scope.Actor,scope);}}
 internal Game.Runtime.SourceCanonicalProfileScope BeginSourceEconomyProfileBinding(Entity entity,FixedString64Bytes attempt,string structureId){if(bank==null)return null;if(!bank.IsFreshSourceOwnedBy(this)||canonicalFactoryScope!=null||canonicalProfileScope!=null)throw new NotSupportedException("Fresh source native profile-binding scope required");if(!Exists(entity)||!HasComponent<SkirmishAttemptOwnedComponent>(entity)||!HasComponent<SkirmishStructureIdentityComponent>(entity))throw new NotSupportedException("Original native structure binding must precede profile creation");var own=GetComponentData<SkirmishAttemptOwnedComponent>(entity);var identity=GetComponentData<SkirmishStructureIdentityComponent>(entity);if(!own.SessionId.Equals(attempt)||own.IsStructure==0||identity.StructureId.ToString()!=structureId)throw new NotSupportedException("Profile-binding attempt/structure identity mismatch");bool canAdd=false;if(canonicalPendingBirths.TryGetValue(entity,out var birth)){if(!birth.Completed||birth.Created!=1||birth.Actor!=entity||!ReferenceEquals(birth.Manager,this)||own.FactionId!=birth.Permit.Request.FactionId||!HasComponent<RuntimeBuildingCombatInfo>(entity))throw new NotSupportedException("Profile-binding factory lineage/faction mismatch");var info=GetComponentData<RuntimeBuildingCombatInfo>(entity);if(info.RuntimeBuildingId!=birth.RuntimeId||info.OwnerFactionId!=own.FactionId)throw new NotSupportedException("Original owner assignment must precede economy profile");if(!birth.Permit.Factory.CanonicalCollection.ContainsBuilding(birth.RuntimeId)||!HasComponent<Game.Runtime.SkirmishNativeBuildingCheckpointRecord>(entity))throw new NotSupportedException("Original canonical registration must commit before profile binding");var checkpoint=GetComponentObject<Game.Runtime.SkirmishNativeBuildingCheckpointRecord>(entity);if(checkpoint?.Building==null||checkpoint.Building.Id!=birth.RuntimeId||checkpoint.Building.CombatEntity!=entity)throw new NotSupportedException("Profile binding requires the same actually registered source building");canAdd=bank.Contains(entity);}canonicalProfileScope=new Game.Runtime.SourceCanonicalProfileScope(this,entity,canAdd);return canonicalProfileScope;}
 internal void EndCanonicalProfile(Game.Runtime.SourceCanonicalProfileScope scope){if(!ReferenceEquals(canonicalProfileScope,scope))throw new InvalidOperationException("Canonical profile scope lineage");canonicalProfileScope=null;canonicalPendingBirths.Remove(scope.Actor);}
 internal void ForgetCanonicalBirth(Entity entity){canonicalPendingBirths.Remove(entity);}
 internal void AddCanonicalSourceComponent(Entity entity,Type type,object value){if(bank==null||!bank.IsFreshSourceOwnedBy(this))throw new NotSupportedException("Canonical storage structural birth needs explicit bank domain extension");if(type==typeof(BuildingResourceStorageComponent)){var scope=canonicalFactoryScope;if(scope==null)throw new NotSupportedException("Actual source factory storage birth scope required");scope.ValidateActor(entity);var storage=(BuildingResourceStorageComponent)value;var info=GetComponentData<RuntimeBuildingCombatInfo>(entity);if(storage.RuntimeBuildingId!=scope.RuntimeId||storage.OwnerFactionId!=info.OwnerFactionId)throw new NotSupportedException("Original native storage identity/faction mismatch");bank.AppendFreshSourceStorage(entity,storage,this);}else if(type==typeof(BuildingResourceProductionProfileComponent)){var scope=canonicalProfileScope;if(scope==null||scope.Disposed||scope.Actor!=entity||!scope.CanAdd)throw new NotSupportedException("Original native facility profile binding required");bank.AddFreshSourceProfile(entity,(BuildingResourceProductionProfileComponent)value,this);}else throw new NotSupportedException("Unexpected canonical source component");MarkWrite(entity,type);Touch(type);}
}
